"""Standalone, offline listening page. Embeds the exact runtime audio bytes."""
from pathlib import Path
import base64,json
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
manifest=json.loads((HERE/'manifest.json').read_text(encoding='utf8'))
names={'sfx_panel_slide':'展开面板','sfx_draw_tick':'招募抽取','sfx_wish_start':'祈愿启动','sfx_wish_gather':'祈愿汇聚','sfx_wish_burst':'祈愿揭晓','sfx_boss_skill':'首领技能','sfx_ui_back':'返回与关闭','sfx_ui_error':'操作失败','sfx_upgrade':'培养与加点','sfx_equip':'放置与锁定','sfx_chest':'打开宝箱','sfx_learn_complete':'学习完成',
'bgm_home':'Town Theme RPG · 战斗外','bgm_battle':'Battle Theme A · 普通战斗','bgm_boss':'Epic Boss Battle · 首领战',
'sfx_ui_confirm':'界面确认','sfx_bubble_pop':'泡泡破裂','sfx_bubble_rub':'擦开泡泡','sfx_collect':'领取与收录','sfx_rare_reveal':'稀有揭晓','sfx_victory':'胜利','sfx_defeat':'失败',
'sfx_attack_melee':'近战普攻','sfx_attack_projectile':'远程普攻','sfx_attack_magic':'法术普攻','sfx_hit_soft':'轻受击','sfx_heal':'普通治疗','sfx_core_hit':'核心受损',
'sfx_skill_stone':'岩盾技能','sfx_skill_spike':'尖刺技能','sfx_skill_crystal':'晶炮技能','sfx_skill_leaf':'叶灵技能','sfx_skill_bubble':'泡泡技能',
'sfx_fusion_start':'合成启动','sfx_fusion_complete':'合成揭晓','sfx_purchase':'购买成功','sfx_learn':'学习技能','sfx_wave_start':'波次开始','sfx_boss_arrive':'首领登场','sfx_shield':'获得护盾','sfx_revive':'复活','sfx_critical':'暴击'}
data=[]
for a in manifest['assets']:
 path=ROOT/a['runtime'];mime='audio/ogg' if path.suffix=='.ogg' else 'audio/wav'
 data.append({'key':a['key'],'name':names[a['key']],'duration':a['duration'],'src':'data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()})
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>哥喂龟 · 音乐与音效试听</title>
<style>*{box-sizing:border-box}body{margin:0;background:#eef4ef;color:#173d39;font:16px/1.6 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:48px 24px}small,.muted{color:#53716b}h1{font-size:38px;margin:8px 0}h2{font-size:23px;margin:32px 0 14px}p{max-width:800px}button{cursor:pointer;border:1px solid #b9cec5;border-radius:12px;background:white;color:#174b42;padding:12px 16px;font:inherit}button:hover{background:#dcefe3}button:focus-visible{outline:3px solid #00866c;outline-offset:3px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.track{padding:24px;border:1px solid #c7d9d1;border-radius:20px;background:white}.track button{background:#1c6659;color:white;width:100%;margin-top:16px}.track b{display:block;font-size:20px}.bar{display:flex;gap:24px;flex-wrap:wrap;align-items:center;padding:20px 0}.bar label{display:flex;gap:10px;align-items:center}input{accent-color:#287865}#status{padding:16px 20px;border-radius:12px;background:#dceae2;min-height:58px}.effects button{text-align:left}.effects small{display:block;font-size:12px}footer{border-top:1px solid #c6d9cf;margin-top:40px;padding-top:20px}a{color:#146f63}</style>
<main><small>哥喂龟 / SOUND LIBRARY / 2026.09.16</small><h1>海岛的声音</h1><p>三种场景音乐，三十九个动作反馈。先播放背景音乐，再点下方音效，试听技能、合成与奖励的叠加效果。</p>
<div class="bar"><label>音乐 <input id="musicVolume" aria-label="音乐音量" type="range" min="0" max="1" step=".05" value=".6"></label><label>音效 <input id="effectsVolume" aria-label="音效音量" type="range" min="0" max="1" step=".05" value=".7"></label><button id="stop">全部停止</button></div>
<p id="status" role="status" aria-live="polite">点击任一音乐或音效开始试听。</p><h2>场景音乐</h2><div id="music" class="grid"></div>
<h2>合成与成长</h2><div id="growth" class="grid effects"></div><h2>技能与战斗</h2><div id="combat" class="grid effects"></div><h2>界面与结果</h2><div id="interface" class="grid effects"></div>
<footer><b>免费商用 · CC0 1.0</b><p class="muted">音乐：cynicmusic、Juhani Junkala（SubspaceAudio）。用户已选择 A 套奇幻管弦。音效：Kenney。此页嵌入游戏运行素材，可离线打开。声音风格与设备外放听感请以实际试听为准。</p><p><a href="https://opengameart.org/content/town-theme-rpg">Town Theme RPG</a> · <a href="https://opengameart.org/content/battle-theme-a">Battle Theme A</a> · <a href="https://opengameart.org/content/boss-battle-music">Epic Boss Battle</a> · <a href="https://kenney.nl/assets/interface-sounds">Kenney</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/">CC0 许可</a></p></footer></main>
<script>const assets=__DATA__;let current=null,fade=1;const effects=new Set();const status=document.querySelector('#status'),mv=document.querySelector('#musicVolume'),ev=document.querySelector('#effectsVolume');
function stop(){if(current)current.audio.pause();current=null;for(const a of effects)a.pause();effects.clear();status.textContent='已停止全部声音。'}
document.querySelector('#stop').onclick=stop;mv.oninput=()=>{if(current)current.audio.volume=Number(mv.value)*fade};ev.oninput=()=>{for(const a of effects)a.volume=Number(ev.value)*.8};
async function playMusic(item){if(current?.key===item.key)return;const previous=current;const audio=new Audio(item.src);audio.loop=true;audio.volume=0;current={key:item.key,audio,name:item.name};fade=0;if(previous)previous.audio.pause();try{await audio.play();status.textContent='正在播放：'+item.name+'（循环）';const started=performance.now();function rise(t){if(current?.audio!==audio)return;fade=Math.min(1,(t-started)/400);audio.volume=Number(mv.value)*fade;if(fade<1)requestAnimationFrame(rise);}requestAnimationFrame(rise);}catch(e){status.textContent='播放失败：'+e.message;}}
async function effect(item){if(effects.size>=6){const first=effects.values().next().value;first.pause();effects.delete(first);}const audio=new Audio(item.src);audio.volume=Number(ev.value)*.8;effects.add(audio);audio.onended=()=>effects.delete(audio);try{await audio.play();status.textContent=(current?'背景：'+current.name+' ｜ ':'')+'音效：'+item.name;}catch(e){effects.delete(audio);status.textContent='播放失败：'+e.message;}}
for(const item of assets){if(item.key.startsWith('bgm')){const card=document.createElement('div');card.className='track';const b=document.createElement('b');b.textContent=item.name;const small=document.createElement('small');small.textContent=item.duration.toFixed(1)+' 秒 · 完整循环';const button=document.createElement('button');button.textContent='播放 '+item.name;button.onclick=()=>playMusic(item);card.append(b,small,button);document.querySelector('#music').append(card);}else{const button=document.createElement('button');button.textContent=item.name;const small=document.createElement('small');small.textContent=item.duration.toFixed(2)+' 秒';button.append(small);button.onclick=()=>effect(item);const group=/fusion|purchase|learn|collect|rare|upgrade|equip|chest/.test(item.key)?'growth':/attack|skill|hit|heal|wave|boss|shield|revive|critical/.test(item.key)?'combat':'interface';document.getElementById(group).append(button);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});</script></html>'''
(ROOT/'output/audio-cc0-review.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False)),encoding='utf8')
print('output/audio-cc0-review.html')
